import os
from typing import Any, Dict, List, Optional

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _normalize_threshold(threshold: float) -> float:
    try:
        threshold = float(threshold)
    except (TypeError, ValueError):
        threshold = 0.5
    return max(0.0, min(1.0, threshold))


def _severity_from_scores(scores: Dict[str, Any]) -> str:
    if not scores:
        return "low"
    try:
        max_score = max(float(v.get("summaryScore", {}).get("value", 0.0)) for v in scores.values())
    except Exception:
        max_score = 0.0
    if max_score >= 0.9:
        return "critical"
    if max_score >= 0.7:
        return "high"
    if max_score >= 0.4:
        return "medium"
    return "low"


def moderate_batch_messages(
    messages: List[str],
    threshold: float = 0.5,
    attributes: Optional[List[str]] = None,
    api_key: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Moderate a batch of messages using Perspective API and return per-message decisions.

    Args:
        messages: List of user-generated messages to moderate.
        threshold: Score threshold for flagging content, in [0, 1].
        attributes: Optional list of Perspective attributes to request.
        api_key: Optional Perspective API key; falls back to PERSPECTIVE_API_KEY.

    Returns:
        List of dicts, one per message, with decision details.
    """
    api_key = api_key or os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise ValueError("Missing Perspective API key. Set PERSPECTIVE_API_KEY or pass api_key.")

    threshold = _normalize_threshold(threshold)
    if not attributes:
        attributes = ["TOXICITY", "SEVERE_TOXICITY", "INSULT", "THREAT", "PROFANITY", "IDENTITY_ATTACK"]

    headers = {"Content-Type": "application/json"}
    results: List[Dict[str, Any]] = []

    for message in messages:
        if not isinstance(message, str):
            message = "" if message is None else str(message)

        payload = {
            "comment": {"text": message},
            "languages": ["en"],
            "requestedAttributes": {attr: {} for attr in attributes},
            "doNotStore": True,
        }
        params = {"key": api_key}

        try:
            response = requests.post(
                PERSPECTIVE_API_URL,
                params=params,
                headers=headers,
                json=payload,
                timeout=20,
            )
            response.raise_for_status()
            data = response.json()
            attr_scores = data.get("attributeScores", {})

            scores: Dict[str, float] = {}
            for attr in attributes:
                try:
                    scores[attr] = float(attr_scores.get(attr, {}).get("summaryScore", {}).get("value", 0.0))
                except (TypeError, ValueError):
                    scores[attr] = 0.0

            max_attr = max(scores, key=scores.get) if scores else None
            max_score = scores[max_attr] if max_attr is not None else 0.0
            flagged = max_score >= threshold

            results.append(
                {
                    "message": message,
                    "flagged": flagged,
                    "decision": "reject" if flagged else "allow",
                    "severity": _severity_from_scores(attr_scores),
                    "scores": scores,
                    "max_attribute": max_attr,
                    "max_score": max_score,
                }
            )
        except requests.RequestException as exc:
            results.append(
                {
                    "message": message,
                    "flagged": False,
                    "decision": "error",
                    "severity": "unknown",
                    "scores": {},
                    "error": str(exc),
                }
            )

    return results
